SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "曹淑妃以病烦辞后位，王德妃以中宫匹帝辞让。", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p010·原文件第15行", "note": "原文：帝将立曹淑妃为后，淑妃谓王德妃曰：“吾素病中烦，倦于接对，妹代我为之。”德妃曰：“中宫敌偶至尊，谁敢干之！”；核对说明：辞让为谈话，不是王氏已当皇后；妹为宫中称呼，未证亲生姐妹。中烦保留为本人病烦陈述，不推医学病名。", "status": "draft", "id": "a0254b0e-132c-5c88-8c61-278b7a00340a", "subject_id": "a3efba1b-1ab1-592f-aa0a-c61b4f07bfab", "source_id": "8b69ec70-d285-523a-ab9d-7d845a097ab8"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "930年三月庚寅立后之前", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p010·原文件第15行", "note": "原文：帝将立曹淑妃为后，淑妃谓王德妃曰：“吾素病中烦，倦于接对，妹代我为之。”德妃曰：“中宫敌偶至尊，谁敢干之！”；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "fbf21b5a-ffd2-59b7-82eb-5b6a44550dca", "subject_id": "a3efba1b-1ab1-592f-aa0a-c61b4f07bfab", "source_id": "8b69ec70-d285-523a-ab9d-7d845a097ab8"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记曹氏（李嗣源后）：被拟立后、向王德妃辞让者。", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p010·原文件第15行", "note": "原文：帝将立曹淑妃为后，淑妃谓王德妃曰：“吾素病中烦，倦于接对，妹代我为之。”德妃曰：“中宫敌偶至尊，谁敢干之！”；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "49ce067f-f287-5d01-bcf1-edf5bc1510bf", "subject_id": "6ef55b9f-6fef-5ad4-b449-50af87f1033f", "source_id": "8b69ec70-d285-523a-ab9d-7d845a097ab8"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "曹氏（李嗣源后）：被拟立后、向王德妃辞让者。", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p010·原文件第15行", "note": "原文：帝将立曹淑妃为后，淑妃谓王德妃曰：“吾素病中烦，倦于接对，妹代我为之。”德妃曰：“中宫敌偶至尊，谁敢干之！”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "1c4433ee-5d71-5715-ab89-883915da4698", "subject_id": "e6d84c7d-29e8-54e8-ab2e-494e9c140a32", "source_id": "8b69ec70-d285-523a-ab9d-7d845a097ab8"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记王德妃（李嗣源妃）：拒绝代立者。", "citation": "